  <script>
    // Normalise eastern Arabic & Persian digits to Western digits
    function toWesternDigits(str) {
      return str
        .replace(/[٠۰]/g, '0')
        .replace(/[١۱]/g, '1')
        .replace(/[٢۲]/g, '2')
        .replace(/[٣۳]/g, '3')
        .replace(/[٤۴]/g, '4')
        .replace(/[٥۵]/g, '5')
        .replace(/[٦۶]/g, '6')
        .replace(/[٧۷]/g, '7')
        .replace(/[٨۸]/g, '8')
        .replace(/[٩۹]/g, '9');
    }

    const inputs = Array.from(document.querySelectorAll('.otp-box'));
    const verifyBtn = document.getElementById('verifyBtn');
    const timerDisplay = document.getElementById('timerDisplay');
    const countdownMessage = document.getElementById('countdownMessage');
    const resendBtn = document.getElementById('resendBtn');

    function checkCompletion() {
      const allFilled = inputs.every(input => input.value.trim().length === 1);
      verifyBtn.disabled = !allFilled;
    }

    inputs.forEach((input, index) => {
      input.addEventListener('input', (e) => {
        let val = toWesternDigits(e.target.value).replace(/\D/g, '');
        if (val.length > 0) {
          input.value = val[val.length - 1]; // take the last valid digit
          input.classList.add('filled');
          if (index < inputs.length - 1) {
            inputs[index + 1].focus();
          }
        } else {
          input.value = '';
          input.classList.remove('filled');
        }
        checkCompletion();
      });

      input.addEventListener('keydown', (e) => {
        if (e.key === 'Backspace') {
          if (!input.value && index > 0) {
            inputs[index - 1].focus();
            inputs[index - 1].value = '';
            inputs[index - 1].classList.remove('filled');
            checkCompletion();
          } else {
            input.classList.remove('filled');
          }
        } else if (e.key === 'ArrowLeft' && index > 0) {
          inputs[index - 1].focus();
        } else if (e.key === 'ArrowRight' && index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
      });

      // Handle pasting whole 6-digit code
      input.addEventListener('paste', (e) => {
        e.preventDefault();
        const clipboardData = (e.clipboardData || window.clipboardData).getData('text');
        const normalised = toWesternDigits(clipboardData).replace(/\D/g, '');
        if (normalised.length > 0) {
          const chars = normalised.slice(0, 6).split('');
          chars.forEach((char, i) => {
            if (inputs[i]) {
              inputs[i].value = char;
              inputs[i].classList.add('filled');
            }
          });
          const focusIndex = Math.min(chars.length, inputs.length - 1);
          inputs[focusIndex].focus();
          checkCompletion();
        }
      });
    });

    // Countdown Timer (0:45)
    let totalSeconds = 45;
    let timerInterval = null;

    function formatTime(seconds) {
      const mins = Math.floor(seconds / 60);
      const secs = seconds % 60;
      return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
    }

    function startTimer() {
      clearInterval(timerInterval);
      countdownMessage.style.display = 'inline-flex';
      resendBtn.style.display = 'none';
      timerDisplay.textContent = formatTime(totalSeconds);

      timerInterval = setInterval(() => {
        totalSeconds--;
        if (totalSeconds >= 0) {
          timerDisplay.textContent = formatTime(totalSeconds);
        } else {
          clearInterval(timerInterval);
          countdownMessage.style.display = 'none';
          resendBtn.style.display = 'inline-block';
        }
      }, 1000);
    }

    function restartCountdown() {
      totalSeconds = 45;
      inputs.forEach(input => {
        input.value = '';
        input.classList.remove('filled');
      });
      inputs[0].focus();
      checkCompletion();
      startTimer();
    }

    function handleVerify() {
      const code = inputs.map(inp => inp.value).join('');
      if (code.length === 6) {
        verifyBtn.disabled = true;
        verifyBtn.innerHTML = `<span>جارٍ التحقق...</span>`;
        setTimeout(() => {
          alert('تم التحقق بنجاح من الرمز: ' + code);
          verifyBtn.disabled = false;
          verifyBtn.innerHTML = `<span>التحقق</span>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="20 6 9 17 4 12"></polyline>
            </svg>`;
        }, 800);
      }
    }

    startTimer();
  </script>
